#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: devbox secrets setup (host only). Re-runnable: finished steps are detected and skipped.
# Usage: bash .devcontainer/host/setup-secrets.sh   (see docs/secrets.md, Setup)
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=/dev/null   # this wizard never persists answers; nothing secret is written to a dotenv

CFG="$HOME/.config/devbox"
REPO="$HOME/src/secrets"
BIN="$HOME/.local/bin"
RUNTIME="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/devbox"
DEVBOX_DIR="${DEVBOX_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"   # this checkout
PUBFILE="$CFG/pubkeys.txt"   # public keys only
export PATH="$BIN:$PATH"

_pub() { grep -E "^$1=" "$PUBFILE" 2>/dev/null | head -n1 | cut -d= -f2-; }

# Append a line to the user's shell rc once.
_rc_add() {
  local line="$1" rc
  case "${SHELL:-}" in */zsh) rc="$HOME/.zshrc" ;; *) rc="$HOME/.bashrc" ;; esac
  if grep -qxF "$line" "$rc" 2>/dev/null; then note "already in $rc"; else
    printf '%s\n' "$line" >> "$rc"; say "added to $rc: $line"
  fi
}

run_wizard() {

TOTAL_STAGES=9

if [[ -f /.containerenv || -n "${REMOTE_CONTAINERS:-}" || "$(id -un)" == dev ]]; then
  warn "This looks like the devcontainer. Run this wizard on the HOST (a normal terminal)."
  confirm "Continue anyway?" || exit 1
fi

banner "devbox secrets setup (host)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools: age, sops, git"
[[ -f "$DEVBOX_DIR/.devcontainer/install-sops-age.sh" ]] \
  || ask DEVBOX_DIR "Path to the devbox checkout on feat/sops-age-secrets:"
[[ -x "$DEVBOX_DIR/.devcontainer/install-sops-age.sh" || -f "$DEVBOX_DIR/.devcontainer/install-sops-age.sh" ]] \
  || { warn "not found: $DEVBOX_DIR/.devcontainer/install-sops-age.sh"; exit 1; }
command -v git >/dev/null || { warn "install git first"; exit 1; }
if command -v sops >/dev/null && command -v age >/dev/null && command -v age-keygen >/dev/null; then
  say "sops $(sops --version 2>&1 | head -n1 | sed 's/^sops //;s/ .*//') and age found."
else
  say "sops/age missing. Installing the pinned, checksum-verified versions into $BIN."
  confirm "Install now?" || exit 1
  mkdir -p "$BIN"
  bash "$DEVBOX_DIR/.devcontainer/install-sops-age.sh" "$BIN"
fi
case ":$PATH:" in *":$BIN:"*) ;; *) warn "$BIN is not on your PATH" ;; esac
_rc_add 'export PATH="$HOME/.local/bin:$PATH"'
pause "Enter for the next stage"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Generate the box key and admin key"
mkdir -p "$CFG" "$REPO"; chmod 700 "$CFG"
if [[ -f "$CFG/box.key.age" && -s "$PUBFILE" ]]; then
  say "Box key already exists and is passphrase-protected: skipping."
else
  [[ -f "$CFG/box.key" || -f "$CFG/admin.key" || -f "$CFG/admin.key.enc" ]] && {
    warn "partial key files exist in $CFG. Move or delete them, then re-run."; exit 1; }
  say "Box key: decrypts dev and preview files only. Admin key: decrypts everything, incl. prod."
  age-keygen -o "$CFG/box.key" 2>&1 | sed 's/^/  /'
  age-keygen -o "$CFG/admin.key" 2>&1 | sed 's/^/  /'
  {
    printf 'BOX_PUB=%s\n' "$(age-keygen -y "$CFG/box.key")"
    printf 'ADMIN_PUB=%s\n' "$(age-keygen -y "$CFG/admin.key")"
  } > "$PUBFILE"
  chmod 600 "$CFG/box.key" "$CFG/admin.key"
  say "Public keys saved to $PUBFILE (public, safe)."
fi
pause "Enter for the next stage"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Back up the admin key, then protect both keys with passphrases"
if [[ -f "$CFG/admin.key" ]]; then
  say "The admin key decrypts prod and everything else. Losing it loses prod."
  step "Create ONE Bitwarden item holding: the contents of $CFG/admin.key and the passphrase"
  step "you are about to choose. (View it in a terminal you trust: cat $CFG/admin.key)"
  open_url "https://vault.bitwarden.com/#/vault"
  confirm "Saved in Bitwarden (key AND the passphrase you will use)?" || { warn "Not shredding anything. Re-run when saved."; exit 1; }
  step "Choose the ADMIN key passphrase (asked twice)."
  age -p -o "$CFG/admin.key.enc" "$CFG/admin.key"
  step "Verify: enter the same passphrase once more."
  age -d "$CFG/admin.key.enc" | grep -q '^AGE-SECRET-KEY-' \
    || { warn "could not decrypt admin.key.enc; plaintext kept. Fix and re-run."; rm -f "$CFG/admin.key.enc"; exit 1; }
  shred -u "$CFG/admin.key"
  say "admin.key shredded; admin.key.enc remains."
else
  say "Admin key already protected: skipping."
fi
if [[ -f "$CFG/box.key" ]]; then
  step "Choose the BOX key passphrase (asked twice). You type this every work session."
  age -p -o "$CFG/box.key.age" "$CFG/box.key"
  step "Verify: enter it once more."
  age -d "$CFG/box.key.age" | grep -q '^AGE-SECRET-KEY-' \
    || { warn "could not decrypt box.key.age; plaintext kept. Fix and re-run."; rm -f "$CFG/box.key.age"; exit 1; }
  shred -u "$CFG/box.key"
  say "box.key shredded; box.key.age remains."
else
  say "Box key already protected: skipping."
fi
_rc_add "export DEVBOX_ADMIN_KEY=\"$CFG/admin.key.enc\""
export DEVBOX_ADMIN_KEY="$CFG/admin.key.enc"
pause "Enter for the next stage"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the secrets repo and .sops.yaml"
BOX_PUB=$(_pub BOX_PUB); ADMIN_PUB=$(_pub ADMIN_PUB)
[[ -n "$BOX_PUB" && -n "$ADMIN_PUB" ]] || { warn "missing public keys in $PUBFILE"; exit 1; }
cd "$REPO"
[[ -d .git ]] || git init -q
if [[ -f .sops.yaml ]]; then
  say ".sops.yaml already exists: leaving it alone."
else
  cat > .sops.yaml <<EOF
creation_rules:
  - path_regex: ^(_global|[^/]+)/(dev|preview)\.env\$
    age: $BOX_PUB,$ADMIN_PUB
  - path_regex: ^[^/]+/prod\.env\$
    age: $ADMIN_PUB
EOF
  git add .sops.yaml && git commit -q -m "init: sops rules" && say "committed .sops.yaml"
fi
pause "Enter for the next stage"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Global values: GH_TOKEN (_global/dev.env)"
cd "$REPO"
if [[ -f _global/dev.env ]]; then
  say "_global/dev.env exists. Change it later with: devbox-secrets edit _global dev"
else
  say "A fine-grained GitHub token for tools in the box. Give it NO access to the secrets repo."
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Pick only the repositories and permissions the box really needs, then generate and copy it."
  TOKEN=""
  ask_secret TOKEN "Paste the token (Enter to skip for now):" || true
  if [[ -n "$TOKEN" ]]; then
    mkdir -p _global
    printf 'GH_TOKEN=%s\n' "$TOKEN" \
      | sops encrypt --filename-override _global/dev.env --input-type dotenv --output-type dotenv /dev/stdin \
      > _global/dev.env.tmp && mv _global/dev.env.tmp _global/dev.env \
      || { rm -f _global/dev.env.tmp _global/dev.env; warn "encrypt failed"; exit 1; }
    unset TOKEN
    grep -q 'ENC\[' _global/dev.env || { warn "file does not look encrypted; removing"; rm -f _global/dev.env; exit 1; }
    git add _global/dev.env && git commit -q -m "add _global/dev.env" && say "encrypted and committed."
  else
    SKIPPED+=("_global/dev.env not created (no token)")
  fi
fi
pause "Enter for the next stage"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Per-project secret files (optional, repeatable)"
cd "$REPO"
ed="${EDITOR:-vi}"; [[ "$ed" == *--wait* ]] && ed=vi
say "Each file opens in '$ed' as plain KEY=value lines (no quotes, no 'export'). Save to encrypt."
while true; do
  proj=""; envn=""
  ask proj "Project name (Enter when done):" || break
  [[ -z "$proj" ]] && break
  [[ "$proj" =~ ^[A-Za-z0-9_-]+$ ]] || { warn "letters, digits, _ and - only"; continue; }
  ask envn "Environment (dev, preview or prod; prod is admin-only):" || break
  [[ "$envn" =~ ^(dev|preview|prod)$ ]] || { warn "environment must be dev, preview or prod (.sops.yaml has no other rule)"; continue; }
  if [[ -f "$proj/$envn.env" ]]; then
    if grep -q 'ENC\[' "$proj/$envn.env"; then warn "$proj/$envn.env exists; use: devbox-secrets edit $proj $envn"
    else warn "$proj/$envn.env exists but is NOT encrypted. Encrypt it in place: (cd $REPO && sops encrypt --in-place $proj/$envn.env), or delete it and re-run."; fi
    continue
  fi
  mkdir -p "$proj"
  EDITOR="$ed" sops "$proj/$envn.env" || { warn "sops failed or was cancelled"; rm -f "$proj/$envn.env"; continue; }
  [[ -f "$proj/$envn.env" ]] && git add "$proj/$envn.env" && git commit -q -m "add $proj/$envn" && say "committed $proj/$envn.env"
done
pause "Enter for the next stage"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Put devbox-secrets on your PATH"
mkdir -p "$BIN"
ln -sfn "$DEVBOX_DIR/.devcontainer/host/devbox-secrets" "$BIN/devbox-secrets"
chmod +x "$DEVBOX_DIR/.devcontainer/host/devbox-secrets" 2>/dev/null || true
command -v devbox-secrets >/dev/null && say "ok: $(command -v devbox-secrets)" || warn "not on PATH yet; open a new shell"
install -d -m 700 "$RUNTIME"
pause "Enter for the next stage"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Test: unlock, decrypt (values not shown), lock"
cd "$REPO"
if [[ -f _global/dev.env ]]; then
  step "Enter the BOX passphrase."
  if devbox-secrets unlock; then
    n=$(SOPS_AGE_KEY_FILE="$RUNTIME/age.key" sops decrypt --input-type dotenv --output-type dotenv _global/dev.env 2>/dev/null | grep -c '^GH_TOKEN=' || true)
    [[ "$n" == 1 ]] && say "✓ box key decrypts _global/dev.env" || warn "box key could NOT decrypt _global/dev.env"
    devbox-secrets lock && say "✓ locked again"
  else warn "unlock failed"; fi
  step "Enter the ADMIN passphrase."
  n=$(SOPS_AGE_KEY_FILE="$DEVBOX_ADMIN_KEY" sops decrypt --input-type dotenv --output-type dotenv _global/dev.env 2>/dev/null | grep -c '^GH_TOKEN=' || true)
  [[ "$n" == 1 ]] && say "✓ admin key decrypts _global/dev.env" || warn "admin key could NOT decrypt _global/dev.env"
else
  step "No encrypted file yet, so testing unlock only. Enter the BOX passphrase."
  devbox-secrets unlock && say "✓ unlock works" && devbox-secrets lock
fi
pause "Enter for the next stage"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Back up the secrets repo (private remote)"
cd "$REPO"
if git remote get-url origin >/dev/null 2>&1; then
  say "origin is $(git remote get-url origin)"
else
  say "Ciphertext still reveals key names and file names: use a PRIVATE repo."
  if confirm "Add a remote now?"; then
    open_url "https://github.com/new"
    REMOTE=""; ask REMOTE "Remote URL (git@github.com:you/secrets.git):" || true
    [[ -n "$REMOTE" ]] && git remote add origin "$REMOTE"
  fi
fi
if git remote get-url origin >/dev/null 2>&1; then
  git push -u origin "$(git branch --show-current)" && say "pushed." || SKIPPED+=("push the secrets repo: git -C $REPO push -u origin HEAD")
else
  SKIPPED+=("no remote on $REPO: add a private one and push")
fi

SKIPPED+=("open a NEW terminal so PATH and DEVBOX_ADMIN_KEY apply")
SKIPPED+=("rebuild the devbox container on feat/sops-age-secrets, then: bash tests/verify-on-host.sh --from 9")
SKIPPED+=("add to each project's AGENTS.md: never print env/secrets; use with-secrets <project> <env> -- <cmd>")
finish
}

run_wizard "$@"; exit
